import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { toast } from 'react-toastify';

export default function InfluencerUpload() {
    const navigate = useNavigate();
    const [uploadData, setUploadData] = useState({
        title: '',
        description: '',
        category: '',
        video: null,
        thumbnail: null,
        associationType: '', // 'seller' or 'brand'
        selectedSeller: '',
        selectedBrand: '',
        selectedProducts: []
    });
    const [loading, setLoading] = useState(false);
    const [categories, setCategories] = useState([]);
    const [sellers, setSellers] = useState([]);
    const [brands, setBrands] = useState([]);
    const [sellerProducts, setSellerProducts] = useState([]);
    const [brandProducts, setBrandProducts] = useState([]);
    const [reels, setReels] = useState([]);
    const [showUploadForm, setShowUploadForm] = useState(false);

    useEffect(() => {
        // Initialize Lucide icons
        if (window.lucide) {
            window.lucide.createIcons();
        }
        
        // Load initial data
        loadCategories();
        loadReels();
    }, []);

    const loadCategories = async () => {
        try {
            // In a real implementation, this would fetch from the backend
            // For now, we'll use simulated data
            setTimeout(() => {
                setCategories([
                    { id: 1, name: 'Fashion' },
                    { id: 2, name: 'Food' },
                    { id: 3, name: 'Fitness' },
                    { id: 4, name: 'Travel' },
                    { id: 5, name: 'Technology' }
                ]);
            }, 300);
        } catch (error) {
            console.error('Error loading categories:', error);
            toast.error('Failed to load categories');
        }
    };

    const loadReels = async () => {
        try {
            // In a real implementation, this would fetch from:
            // GET /Studio/Reels/my-reels
            // For now, we'll use simulated data
            setTimeout(() => {
                setReels([
                    {
                        id: 1,
                        title: 'Summer Fashion Trends',
                        category_name: 'Fashion',
                        status: 'approved',
                        views: 1250,
                        likes: 342,
                        created_at: '2023-06-15'
                    },
                    {
                        id: 2,
                        title: 'Cooking Pasta Recipe',
                        category_name: 'Food',
                        status: 'pending',
                        views: 0,
                        likes: 0,
                        created_at: '2023-06-18'
                    }
                ]);
            }, 300);
        } catch (error) {
            console.error('Error loading reels:', error);
            toast.error('Failed to load reels');
        }
    };

    const loadSellers = async () => {
        if (sellers.length > 0) return; // Already loaded
        
        try {
            setLoading(true);
            // In a real implementation, this would fetch from:
            // GET /Studio/Reels/sellers
            // For now, we'll use simulated data
            setTimeout(() => {
                setSellers([
                    { vendor_id: 1, firstname: 'John', lastname: 'Fashion Store' },
                    { vendor_id: 2, firstname: 'Tech', lastname: 'Gadgets Ltd' },
                    { vendor_id: 3, firstname: 'Beauty', lastname: 'Essentials' }
                ]);
                setLoading(false);
            }, 500);
        } catch (error) {
            console.error('Error loading sellers:', error);
            toast.error('Failed to load sellers');
            setLoading(false);
        }
    };

    const loadBrands = async () => {
        if (brands.length > 0) return; // Already loaded
        
        try {
            setLoading(true);
            // In a real implementation, this would fetch from:
            // GET /Studio/Reels/brands
            // For now, we'll use simulated data
            setTimeout(() => {
                setBrands([
                    { manufacturer_id: 1, name: 'Nike' },
                    { manufacturer_id: 2, name: 'Apple' },
                    { manufacturer_id: 3, name: 'Samsung' },
                    { manufacturer_id: 4, name: 'Adidas' }
                ]);
                setLoading(false);
            }, 500);
        } catch (error) {
            console.error('Error loading brands:', error);
            toast.error('Failed to load brands');
            setLoading(false);
        }
    };

    const loadSellerProducts = async (vendorId) => {
        try {
            setLoading(true);
            // In a real implementation, this would fetch from:
            // GET /Studio/Reels/sellers/:vendorId/products
            // For now, we'll use simulated data
            setTimeout(() => {
                setSellerProducts([
                    { product_id: 1, name: 'Summer Dress', model: 'SD-001', price: 29.99 },
                    { product_id: 2, name: 'Winter Coat', model: 'WC-002', price: 79.99 },
                    { product_id: 3, name: 'Spring Collection', model: 'SC-003', price: 49.99 }
                ]);
                setLoading(false);
            }, 500);
        } catch (error) {
            console.error('Error loading seller products:', error);
            toast.error('Failed to load seller products');
            setLoading(false);
        }
    };

    const loadBrandProducts = async (brandId) => {
        try {
            setLoading(true);
            // In a real implementation, this would fetch from:
            // GET /Studio/Reels/brands/:brandId/products
            // For now, we'll use simulated data
            setTimeout(() => {
                setBrandProducts([
                    { product_id: 1, name: 'iPhone 15', model: 'IP15-001', price: 999.99 },
                    { product_id: 2, name: 'MacBook Pro', model: 'MBP-002', price: 1999.99 },
                    { product_id: 3, name: 'AirPods', model: 'AP-003', price: 199.99 }
                ]);
                setLoading(false);
            }, 500);
        } catch (error) {
            console.error('Error loading brand products:', error);
            toast.error('Failed to load brand products');
            setLoading(false);
        }
    };

    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setUploadData(prev => ({
            ...prev,
            [name]: value
        }));
    };

    const handleFileChange = (e, fieldName) => {
        const file = e.target.files[0];
        if (file) {
            setUploadData(prev => ({
                ...prev,
                [fieldName]: file
            }));
        }
    };

    const handleAssociationTypeChange = (type) => {
        setUploadData(prev => ({
            ...prev,
            associationType: type,
            selectedSeller: '',
            selectedBrand: '',
            selectedProducts: []
        }));
        
        // Load sellers or brands based on selection
        if (type === 'seller') {
            loadSellers();
        } else if (type === 'brand') {
            loadBrands();
        }
    };

    const handleSellerChange = (vendorId) => {
        setUploadData(prev => ({
            ...prev,
            selectedSeller: vendorId,
            selectedProducts: []
        }));
        
        // Load seller products
        if (vendorId) {
            loadSellerProducts(vendorId);
        } else {
            setSellerProducts([]);
        }
    };

    const handleBrandChange = (brandId) => {
        setUploadData(prev => ({
            ...prev,
            selectedBrand: brandId,
            selectedProducts: []
        }));
        
        // Load brand products
        if (brandId) {
            loadBrandProducts(brandId);
        } else {
            setBrandProducts([]);
        }
    };

    const handleProductSelection = (productId) => {
        setUploadData(prev => {
            const isSelected = prev.selectedProducts.includes(productId);
            
            if (isSelected) {
                // Remove product from selection
                return {
                    ...prev,
                    selectedProducts: prev.selectedProducts.filter(id => id !== productId)
                };
            } else {
                // Add product to selection (max 3)
                if (prev.selectedProducts.length >= 3) {
                    toast.warn('You can select maximum 3 products');
                    return prev;
                }
                return {
                    ...prev,
                    selectedProducts: [...prev.selectedProducts, productId]
                };
            }
        });
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        
        if (!uploadData.title || !uploadData.category || !uploadData.video || 
            !uploadData.associationType || 
            (uploadData.associationType === 'seller' && !uploadData.selectedSeller) ||
            (uploadData.associationType === 'brand' && !uploadData.selectedBrand) ||
            uploadData.selectedProducts.length === 0) {
            toast.error('Please fill in all required fields');
            return;
        }

        setLoading(true);
        
        try {
            // Prepare form data for upload
            const formData = new FormData();
            formData.append('title', uploadData.title);
            formData.append('description', uploadData.description);
            formData.append('categoryId', uploadData.category);
            formData.append('associationType', uploadData.associationType);
            formData.append('selectedSeller', uploadData.selectedSeller);
            formData.append('selectedBrand', uploadData.selectedBrand);
            formData.append('selectedProducts', JSON.stringify(uploadData.selectedProducts));
            
            if (uploadData.video) {
                formData.append('video', uploadData.video);
            }
            
            if (uploadData.thumbnail) {
                formData.append('thumbnail', uploadData.thumbnail);
            }
            
            // In a real implementation, this would POST to:
            // POST /Studio/Reels/upload
            // For now, we'll simulate the upload process
            setTimeout(() => {
                toast.success('Reel uploaded successfully!');
                // Add new reel to the list
                const newReel = {
                    id: reels.length + 1,
                    title: uploadData.title,
                    category_name: categories.find(c => c.id == uploadData.category)?.name || 'Unknown',
                    status: 'pending',
                    views: 0,
                    likes: 0,
                    created_at: new Date().toISOString().split('T')[0]
                };
                setReels(prev => [newReel, ...prev]);
                setShowUploadForm(false);
                resetForm();
                setLoading(false);
            }, 2000);
        } catch (error) {
            console.error('Upload error:', error);
            toast.error('Upload failed: ' + error.message);
            setLoading(false);
        }
    };

    const resetForm = () => {
        setUploadData({
            title: '',
            description: '',
            category: '',
            video: null,
            thumbnail: null,
            associationType: '',
            selectedSeller: '',
            selectedBrand: '',
            selectedProducts: []
        });
        setSellerProducts([]);
        setBrandProducts([]);
    };

    const getStatusBadge = (status) => {
        switch (status) {
            case 'approved':
                return <span className="badge bg-success">Approved</span>;
            case 'pending':
                return <span className="badge bg-warning">Pending</span>;
            case 'rejected':
                return <span className="badge bg-danger">Rejected</span>;
            default:
                return <span className="badge bg-secondary">Unknown</span>;
        }
    };

    return (
        <div className="row">
            <div className="col-12">
                <div className="page-title-box d-flex align-items-center justify-content-between">
                    <h4 className="page-title mb-0">Reels Management</h4>
                </div>
            </div>

            <div className="col-12">
                <div className="card">
                    <div className="card-header d-flex align-items-center justify-content-between">
                        <h5 className="card-title mb-0">Uploaded Reels</h5>
                        <button 
                            className="btn btn-success" 
                            onClick={() => setShowUploadForm(!showUploadForm)}
                        >
                            <i className="ri-add-line me-1"></i>
                            {showUploadForm ? 'Cancel' : 'Add Reel'}
                        </button>
                    </div>
                    <div className="card-body">
                        {showUploadForm ? (
                            <form onSubmit={handleSubmit}>
                                <div className="row">
                                    <div className="col-md-8">
                                        <div className="mb-3">
                                            <label htmlFor="title" className="form-label">
                                                Title <span className="text-danger">*</span>
                                            </label>
                                            <input
                                                type="text"
                                                className="form-control"
                                                id="title"
                                                name="title"
                                                placeholder="Enter reel title"
                                                value={uploadData.title}
                                                onChange={handleInputChange}
                                                disabled={loading}
                                                required
                                            />
                                        </div>

                                        <div className="mb-3">
                                            <label htmlFor="description" className="form-label">
                                                Description
                                            </label>
                                            <textarea
                                                className="form-control"
                                                id="description"
                                                name="description"
                                                rows="4"
                                                placeholder="Enter reel description"
                                                value={uploadData.description}
                                                onChange={handleInputChange}
                                                disabled={loading}
                                            ></textarea>
                                        </div>

                                        <div className="mb-3">
                                            <label htmlFor="category" className="form-label">
                                                Category <span className="text-danger">*</span>
                                            </label>
                                            <select
                                                className="form-select"
                                                id="category"
                                                name="category"
                                                value={uploadData.category}
                                                onChange={handleInputChange}
                                                disabled={loading}
                                                required
                                            >
                                                <option value="">Select a category</option>
                                                {categories.map(category => (
                                                    <option key={category.id} value={category.id}>
                                                        {category.name}
                                                    </option>
                                                ))}
                                            </select>
                                        </div>

                                        <div className="mb-3">
                                            <label className="form-label">
                                                Associate With <span className="text-danger">*</span>
                                            </label>
                                            <div className="d-flex gap-3">
                                                <div className="form-check">
                                                    <input
                                                        className="form-check-input"
                                                        type="radio"
                                                        name="associationType"
                                                        id="associateSeller"
                                                        value="seller"
                                                        checked={uploadData.associationType === 'seller'}
                                                        onChange={() => handleAssociationTypeChange('seller')}
                                                        disabled={loading}
                                                    />
                                                    <label className="form-check-label" htmlFor="associateSeller">
                                                        Seller
                                                    </label>
                                                </div>
                                                <div className="form-check">
                                                    <input
                                                        className="form-check-input"
                                                        type="radio"
                                                        name="associationType"
                                                        id="associateBrand"
                                                        value="brand"
                                                        checked={uploadData.associationType === 'brand'}
                                                        onChange={() => handleAssociationTypeChange('brand')}
                                                        disabled={loading}
                                                    />
                                                    <label className="form-check-label" htmlFor="associateBrand">
                                                        Brand
                                                    </label>
                                                </div>
                                            </div>
                                        </div>

                                        {uploadData.associationType === 'seller' && (
                                            <div className="mb-3">
                                                <label htmlFor="selectedSeller" className="form-label">
                                                    Select Seller <span className="text-danger">*</span>
                                                </label>
                                                <select
                                                    className="form-select"
                                                    id="selectedSeller"
                                                    name="selectedSeller"
                                                    value={uploadData.selectedSeller}
                                                    onChange={(e) => handleSellerChange(e.target.value)}
                                                    disabled={loading}
                                                    required
                                                >
                                                    <option value="">Select a seller</option>
                                                    {sellers.map(seller => (
                                                        <option key={seller.vendor_id} value={seller.vendor_id}>
                                                            {seller.firstname} {seller.lastname}
                                                        </option>
                                                    ))}
                                                </select>

                                                {sellerProducts.length > 0 && (
                                                    <div className="mt-3">
                                                        <label className="form-label">
                                                            Select Products (Max 3) <span className="text-danger">*</span>
                                                        </label>
                                                        <div className="row">
                                                            {sellerProducts.map(product => (
                                                                <div className="col-md-6" key={product.product_id}>
                                                                    <div className="form-check">
                                                                        <input
                                                                            className="form-check-input"
                                                                            type="checkbox"
                                                                            id={`product-${product.product_id}`}
                                                                            checked={uploadData.selectedProducts.includes(product.product_id)}
                                                                            onChange={() => handleProductSelection(product.product_id)}
                                                                            disabled={loading}
                                                                        />
                                                                        <label className="form-check-label" htmlFor={`product-${product.product_id}`}>
                                                                            {product.name} ({product.model}) - ${product.price}
                                                                        </label>
                                                                    </div>
                                                                </div>
                                                            ))}
                                                        </div>
                                                    </div>
                                                )}
                                            </div>
                                        )}

                                        {uploadData.associationType === 'brand' && (
                                            <div className="mb-3">
                                                <label htmlFor="selectedBrand" className="form-label">
                                                    Select Brand <span className="text-danger">*</span>
                                                </label>
                                                <select
                                                    className="form-select"
                                                    id="selectedBrand"
                                                    name="selectedBrand"
                                                    value={uploadData.selectedBrand}
                                                    onChange={(e) => handleBrandChange(e.target.value)}
                                                    disabled={loading}
                                                    required
                                                >
                                                    <option value="">Select a brand</option>
                                                    {brands.map(brand => (
                                                        <option key={brand.manufacturer_id} value={brand.manufacturer_id}>
                                                            {brand.name}
                                                        </option>
                                                    ))}
                                                </select>

                                                {brandProducts.length > 0 && (
                                                    <div className="mt-3">
                                                        <label className="form-label">
                                                            Select Products (Max 3) <span className="text-danger">*</span>
                                                        </label>
                                                        <div className="row">
                                                            {brandProducts.map(product => (
                                                                <div className="col-md-6" key={product.product_id}>
                                                                    <div className="form-check">
                                                                        <input
                                                                            className="form-check-input"
                                                                            type="checkbox"
                                                                            id={`product-${product.product_id}`}
                                                                            checked={uploadData.selectedProducts.includes(product.product_id)}
                                                                            onChange={() => handleProductSelection(product.product_id)}
                                                                            disabled={loading}
                                                                        />
                                                                        <label className="form-check-label" htmlFor={`product-${product.product_id}`}>
                                                                            {product.name} ({product.model}) - ${product.price}
                                                                        </label>
                                                                    </div>
                                                                </div>
                                                            ))}
                                                        </div>
                                                    </div>
                                                )}
                                            </div>
                                        )}
                                    </div>

                                    <div className="col-md-4">
                                        <div className="mb-3">
                                            <label className="form-label">
                                                Video <span className="text-danger">*</span>
                                            </label>
                                            <div className="input-group">
                                                <input
                                                    type="file"
                                                    className="form-control"
                                                    accept="video/*"
                                                    onChange={(e) => handleFileChange(e, 'video')}
                                                    disabled={loading}
                                                    required
                                                />
                                            </div>
                                            <div className="form-text">
                                                MP4, MOV, AVI formats allowed. Max size: 100MB
                                            </div>
                                        </div>

                                        <div className="mb-3">
                                            <label className="form-label">
                                                Thumbnail
                                            </label>
                                            <div className="input-group">
                                                <input
                                                    type="file"
                                                    className="form-control"
                                                    accept="image/*"
                                                    onChange={(e) => handleFileChange(e, 'thumbnail')}
                                                    disabled={loading}
                                                />
                                            </div>
                                            <div className="form-text">
                                                JPG, PNG formats allowed. Recommended size: 1280x720
                                            </div>
                                        </div>
                                    </div>
                                </div>

                                <div className="d-flex gap-2">
                                    <button
                                        type="button"
                                        className="btn btn-secondary"
                                        onClick={() => setShowUploadForm(false)}
                                        disabled={loading}
                                    >
                                        Cancel
                                    </button>
                                    <button
                                        type="submit"
                                        className="btn btn-success"
                                        disabled={loading}
                                    >
                                        {loading ? (
                                            <>
                                                <span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>
                                                Uploading...
                                            </>
                                        ) : (
                                            <>
                                                <i className="ri-upload-line me-1"></i> Upload Reel
                                            </>
                                        )}
                                    </button>
                                </div>
                            </form>
                        ) : (
                            <>
                                {reels.length === 0 ? (
                                    <div className="text-center py-5">
                                        <h5>No reels found</h5>
                                        <p className="text-muted">Upload your first reel to get started.</p>
                                    </div>
                                ) : (
                                    <div className="table-responsive">
                                        <table className="table table-hover align-middle mb-0">
                                            <thead>
                                                <tr>
                                                    <th>Title</th>
                                                    <th>Category</th>
                                                    <th>Status</th>
                                                    <th>Views</th>
                                                    <th>Likes</th>
                                                    <th>Date</th>
                                                    <th>Actions</th>
                                                </tr>
                                            </thead>
                                            <tbody>
                                                {reels.map((reel) => (
                                                    <tr key={reel.id}>
                                                        <td>{reel.title}</td>
                                                        <td>{reel.category_name}</td>
                                                        <td>{getStatusBadge(reel.status)}</td>
                                                        <td>{reel.views}</td>
                                                        <td>{reel.likes}</td>
                                                        <td>{new Date(reel.created_at).toLocaleDateString()}</td>
                                                        <td>
                                                            <button className="btn btn-sm btn-soft-info me-1">
                                                                <i className="ri-eye-line"></i>
                                                            </button>
                                                            <button className="btn btn-sm btn-soft-warning me-1">
                                                                <i className="ri-edit-line"></i>
                                                            </button>
                                                            <button className="btn btn-sm btn-soft-danger">
                                                                <i className="ri-delete-bin-line"></i>
                                                            </button>
                                                        </td>
                                                    </tr>
                                                ))}
                                            </tbody>
                                        </table>
                                    </div>
                                )}
                            </>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
}
